import { BaseLitElement, webComponent } from '@domg-wc/common';
import { vlIconStyles } from '@domg-wc/components/atom';
import { CSSResult, html, TemplateResult } from 'lit';

// vlIconStyles bevat de opmaak van .vl-icon en de mapping van elke icoonnaam op het icon-font. Het font
// vlaanderen-icon en de variabele --vl-icon-font komen uit @domg-wc/styles.
@webComponent('my-component-with-icon')
export class MyComponentWithIcon extends BaseLitElement {
    static get styles(): CSSResult[] {
        return [vlIconStyles];
    }

    render(): TemplateResult {
        return html`
            <span class="vl-icon vl-icon--right-margin vl-icon--paperplane"></span>Verstuur
        `;
    }
}
